 <section class="panel lobby-panel"><div class="lobby-title"><strong>Lobby de amigos</strong><span class="online">SALA LOCAL</span></div><div class="players"><span class="player-dot">🧢</span><span class="player-dot">🦜</span><span class="player-dot">🧒</span><small>Você e seus rivais</small></div><div class="lobby-actions"><input class="room-input" id="roomCode" placeholder="CÓDIGO DA SALA" maxlength="8"><button class="room-btn" id="joinRoom">ENTRAR NA SALA</button></div></section>
 </aside></div></main>
 <section id="gameScreen"><div class="game-top"><div class="game-brand">⚡ BRAVOS <b>• ROYALE</b></div><div class="game-stats"><div class="stat-pill">👥 <b id="aliveCount">12</b> restantes</div><div class="stat-pill">⏱ <b id="timer">00:00</b></div><div class="stat-pill">🎯 <b id="kills">0</b> eliminações</div></div><button class="exit-btn" id="exitBtn">SAIR ✕</button></div><div class="arena"><canvas id="gameCanvas"></canvas><div class="arena-hud"><div class="hud-box">❤️ <b id="healthNum">100</b><div class="health-bar"><i id="healthBar"></i></div></div><div class="hud-box map-label"><b id="arenaName">MORRO DO SOL</b><small id="zoneLabel">Zona fechando em 30s</small></div><div class="hud-box">✦ <b id="gameXp">+0 XP</b></div></div><div class="message" id="gameMessage">Prepare-se!<small>WASD mover • Mouse mirar e atirar</small></div><div class="touch-pad"><div class="touch-control" id="movePad"></div><div class="touch-control fire-touch" id="firePad"></div></div><div class="end-overlay" id="endOverlay"><div class="end-card"><div class="emoji" id="endEmoji">🏆</div><h2 id="endTitle">Booyah!</h2><p id="endText">Você chegou ao topo da arena!</p><button class="play-btn" id="againBtn">JOGAR DE NOVO →</button></div></div></div></section>
 <div class="toast" id="toast"></div></div>
+<script>
+(()=>{'use strict';
+const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
+const chars=[{name:'Bia Boleira',role:'Craque da rua',emoji:'⚽',color:'#f0a94f',unlock:0},{name:'Tico Capoeira',role:'Ginga ligeira',emoji:'🥋',color:'#61a6a0',unlock:100},{name:'Jurema',role:'Guardiã da mata',emoji:'🌺',color:'#9b78ba',unlock:240},{name:'Zeca Arara',role:'Asas do Brasil',emoji:'🦜',color:'#ed7655',unlock:420}];
+const maps={sol:{name:'MORRO DO SOL',grass:'#78a95e',dark:'#699450',accent:'#e9c16e'},mata:{name:'MATA MÍSTICA',grass:'#477e55',dark:'#3a704b',accent:'#8abf6e'}};
+let data=JSON.parse(localStorage.getItem('bravos-save')||'{"xp":30,"coins":120,"games":0}'),chosen=0,mapKey='sol',room='';
+function save(){localStorage.setItem('bravos-save',JSON.stringify(data));renderHome()}
+function showToast(t){let el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
+function renderHome(){let g=$('#characterGrid');g.innerHTML='';chars.forEach((c,i)=>{let locked=data.xp<c.unlock;let b=document.createElement('button');b.className='char-card'+(chosen===i?' selected':'')+(locked?' locked':'');b.disabled=locked;b.innerHTML=`${i===0?'<span class="tag">SEU</span>':''}<span class="char-art">${locked?'🔒':c.emoji}</span><strong>${c.name}</strong><small>${locked?`${c.unlock-data.xp} XP para liberar`:c.role}</small>`;b.onclick=()=>{chosen=i;$('#topAvatar').textContent=c.emoji;renderHome()};g.appendChild(b)});let avail=chars.filter(c=>data.xp>=c.unlock).length;$('#unlockedCount').textContent=`${avail} / 4 disponíveis`;
+let next=chars.find(c=>data.xp<c.unlock);let prev=chars.filter(c=>c.unlock<=data.xp).at(-1);let from=prev?prev.unlock:0,to=next?next.unlock:(prev?.unlock||100);let progress=next?Math.max(0,Math.min(100,(data.xp-from)/(to-from)*100)):100;$('#xpBar').style.width=progress+'%';$('#xpLabel').textContent=`${data.xp} / ${next?to:'MAX'} XP`;$('#unlockHint').textContent=next?`Próximo: ${next.name} — faltam ${next.unlock-data.xp} XP`:'Todos os personagens desbloqueados!';$('#coinCount').textContent=data.coins}
+renderHome();
+$$('.map-card').forEach(b=>b.onclick=()=>{$$('.map-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');mapKey=b.dataset.map});
+$('#joinRoom').onclick=()=>{let input=$('#roomCode');if(input.value.trim()){room=input.value.trim().toUpperCase();input.value=room;showToast(`Sala ${room} selecionada — bots entram para completar a arena`)}else{room=Math.random().toString(36).slice(2,7).toUpperCase();input.value=room;showToast(`Sala criada: ${room} — compartilhe o código com seus amigos`)}};
+// Presença local entre abas abertas no mesmo navegador (não requer servidor).
+let lobbyChannel;try{lobbyChannel=new BroadcastChannel('bravos-lobby');lobbyChannel.postMessage({type:'hello',id:Math.random().toString(36).slice(2),at:Date.now()})}catch{}
+const canvas=$('#gameCanvas'),ctx=canvas.getContext('2d');let game=null,raf=0,keys={},mouse={x:0,y:0,down:false},touch={x:0,y:0,fire:false},lastFrame=0;
+function resize(){let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));ctx.setTransform(d,0,0,d,0,0)}
+window.addEventListener('resize',()=>{if(game)resize()});
+function startGame(){if(game)cancelAnimationFrame(raf);$('#homeScreen').style.display='none';$('#gameScreen').style.display='flex';$('#endOverlay').style.display='none';resize();let p={x:600,y:450,r:14,hp:100,max:100,alive:true,angle:0,speed:210,fire:0,color:chars[chosen].color,name:chars[chosen].name,kind:chosen};let bots=[];for(let i=0;i<11;i++){let a=i/11*Math.PI*2,dist=230+(i%3)*75;bots.push({x:600+Math.cos(a)*dist,y:450+Math.sin(a)*dist,r:13,hp:75,max:75,alive:true,angle:a,speed:95+Math.random()*22,fire:.5+Math.random()*1.5,color:['#e98161','#72a7bc','#e2be69','#9b7cb7','#d789ad','#83a85e'][i%6],name:['Léo Pipa','Nina Jambo','Dudu','Cacau','Joca','Lila'][i%6],kind:(i%4)+1,ai:Math.random()*2,fire:1+Math.random()*2,kills:0});}
+let obstacles=[];for(let i=0;i<32;i++){let x=70+Math.random()*1060,y=70+Math.random()*760;if(Math.hypot(x-600,y-450)>95)obstacles.push({x,y,r:15+Math.random()*17,type:i%4})}let pickups=[];for(let i=0;i<7;i++)pickups.push({x:100+Math.random()*1000,y:100+Math.random()*700,type:i%2,taken:false});
+ game={p,bots,obstacles,pickups,shots:[],time:0,kills:0,xp:0,zone:{x:600,y:450,r:620,target:155,starts:28,duration:95},running:true,over:false,world:{w:1200,h:900},map:mapKey,lastMessage:performance.now(),damageFlash:0};$('#arenaName').textContent=maps[mapKey].name;$('#gameXp').textContent='+0 XP';$('#kills').textContent='0';$('#gameMessage').innerHTML='Prepare-se!<small>WASD mover • Mouse mirar e atirar</small>';$('#gameMessage').style.display='block';setTimeout(()=>{if(game)$('#gameMessage').style.display='none'},2800);$('#endOverlay').style.display='none';lastFrame=performance.now();raf=requestAnimationFrame(loop)}
+$('#playBtn').onclick=startGame;$('#againBtn').onclick=startGame;$('#exitBtn').onclick=()=>{if(game)endGame(false,'Partida encerrada','Volte quando estiver pronto para outra batalha.');setTimeout(()=>{$('#gameScreen').style.display='none';$('#homeScreen').style.display='block'},1100)};
+window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+canvas.addEventListener('pointermove',e=>{let r=canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')mouse.down=true});window.addEventListener('pointerup',()=>mouse.down=false);
+function padBind(el,kind){let origin=null;el.addEventListener('pointerdown',e=>{e.preventDefault();origin={x:e.clientX,y:e.clientY,id:e.pointerId};el.setPointerCapture(e.pointerId);if(kind==='fire')touch.fire=true});el.addEventListener('pointermove',e=>{if(!origin)return;let dx=e.clientX-origin.x,dy=e.clientY-origin.y,len=Math.hypot(dx,dy)||1,m=Math.min(1,len/34);if(kind==='move'){touch.x=dx/len*m;touch.y=dy/len*m}else{touch.fire=true;if(game)game.p.angle=Math.atan2(dy,dx)}});let end=()=>{origin=null;if(kind==='move'){touch.x=0;touch.y=0}else touch.fire=false};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)}padBind($('#movePad'),'move');padBind($('#firePad'),'fire');

