padBind($('#movePad'),'move');padBind($('#firePad'),'fire');
function loop(now){if(!game||!game.running)return;let dt=Math.min(.04,(now-lastFrame)/1000);lastFrame=now;update(dt,now);draw();raf=requestAnimationFrame(loop)}
function update(dt,now){let g=game,p=g.p;g.time+=dt;g.damageFlash=Math.max(0,g.damageFlash-dt);let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touch.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+touch.y,ml=Math.hypot(mx,my);if(ml){p.x+=mx/ml*p.speed*dt;p.y+=my/ml*p.speed*dt}p.x=clamp(p.x,18,1182);p.y=clamp(p.y,18,882);resolveObstacle(p);
let rect=canvas.getBoundingClientRect(),scale=Math.min(rect.width/900,rect.height/610),camX=p.x-rect.width/scale/2,camY=p.y-rect.height/scale/2;let aimX=mouse.x/scale+camX,aimY=mouse.y/scale+camY;let target=nearestTarget(p,g.bots);if(touch.fire||(!mouse.down&&matchMedia('(pointer:coarse)').matches)){if(target){aimX=target.x;aimY=target.y}}p.angle=Math.atan2(aimY-p.y,aimX-p.x);p.fire-=dt;if((mouse.down||keys[' ']||touch.fire)&&p.fire<=0){shoot(p,p.angle,true);p.fire=.25}
for(let b of g.bots){if(!b.alive)continue;b.fire-=dt;b.ai-=dt;let tgt=nearestTarget(b,[p,...g.bots]);if(tgt){let dx=tgt.x-b.x,dy=tgt.y-b.y,d=Math.hypot(dx,dy);b.angle=Math.atan2(dy,dx);if(b.ai<=0){b.ai=.5+Math.random()*1.1;if(d>125){b.x+=dx/d*(35+Math.random()*50);b.y+=dy/d*(35+Math.random()*50)}else if(d<70){b.x-=dx/d*35;b.y-=dy/d*35}}if(d<430&&b.fire<=0){shoot(b,b.angle,false);b.fire=1.15+Math.random()*1.35}}
b.x=clamp(b.x,18,1182);b.y=clamp(b.y,18,882);resolveObstacle(b);if(g.time>g.zone.starts){let z=zoneRadius(g);if(Math.hypot(b.x-g.zone.x,b.y-g.zone.y)>z){b.hp-=dt*7;if(b.hp<=0){b.alive=false}}}}
for(let s of g.shots){if(!s.alive)continue;s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.life<=0||s.x<0||s.y<0||s.x>1200||s.y>900){s.alive=false;continue}for(let ob of g.obstacles)if(Math.hypot(s.x-ob.x,s.y-ob.y)<ob.r+3){s.alive=false;break}if(!s.alive)continue;let targets=s.player?[...g.bots]:[p,...g.bots.filter(b=>b!==s.owner)];for(let t of targets){if(!t.alive)continue;if(Math.hypot(s.x-t.x,s.y-t.y)<t.r+4){t.hp-=s.damage;s.alive=false;if(t.hp<=0){t.alive=false;if(s.player){g.kills++;g.xp+=12}if(t===p)g.damageFlash=.5}break}}}g.shots=g.shots.filter(s=>s.alive);
for(let q of g.pickups)if(!q.taken&&Math.hypot(p.x-q.x,p.y-q.y)<25){q.taken=true;if(q.type===0){p.hp=Math.min(p.max,p.hp+35);g.xp+=5;showToast('Kit médico! +35 de vida')}else{g.xp+=15;showToast('Estrela coletada! +15 XP')}}
if(g.time>g.zone.starts){let z=zoneRadius(g);if(Math.hypot(p.x-g.zone.x,p.y-g.zone.y)>z){p.hp-=dt*9;g.damageFlash=.25}}if(p.hp<=0){p.alive=false;endGame(false,'Que pena!','Você foi eliminado. Ganhou XP por participar.');return}
let alive=g.bots.filter(b=>b.alive).length+1;if(alive<=1){endGame(true,'Booyah!','Você é o último de pé!');return}if(g.time>180){endGame(true,'Booyah!','Você sobreviveu à arena!');return}
$('#aliveCount').textContent=alive;$('#timer').textContent=`${String(Math.floor(g.time/60)).padStart(2,'0')}:${String(Math.floor(g.time%60)).padStart(2,'0')}`;$('#kills').textContent=g.kills;$('#healthNum').textContent=Math.ceil(p.hp);$('#healthBar').style.width=Math.max(0,p.hp)+'%';$('#gameXp').textContent=`+${g.xp} XP`;let remaining=Math.max(0,g.zone.starts-g.time);$('#zoneLabel').textContent=remaining>0?`Zona fecha em ${Math.ceil(remaining)}s`:`Zona segura: ${Math.max(0,Math.ceil(zoneRadius(g)))}m`;$('#zoneLabel').className=remaining<8?'zone-alert':''}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function nearestTarget(from,list){let best=null,bd=Infinity;for(let t of list){if(!t.alive||t===from)continue;let d=Math.hypot(t.x-from.x,t.y-from.y);if(d<bd){bd=d;best=t}}return best}
function shoot(owner,angle,player){let speed=player?520:300;game.shots.push({x:owner.x+Math.cos(angle)*17,y:owner.y+Math.sin(angle)*17,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:player?1.25:1.55,damage:player?25:10,player,owner,alive:true})}
function resolveObstacle(e){for(let o of game.obstacles){let dx=e.x-o.x,dy=e.y-o.y,d=Math.hypot(dx,dy),min=e.r+o.r*.72;if(d<min&&d>0){e.x=o.x+dx/d*min;e.y=o.y+dy/d*min}}}
function zoneRadius(g){if(g.time<=g.zone.starts)return g.zone.r;return Math.max(g.zone.target,g.zone.r-(g.zone.r-g.zone.target)*Math.min(1,(g.time-g.zone.starts)/g.zone.duration))}
function endGame(win,title,text){if(!game||game.over)return;game.over=true;game.running=false;let earned=Math.max(12,Math.floor(game.time/3)+game.kills*12+(win?45:0));data.xp+=earned;data.coins+=Math.floor(earned/5);data.games++;save();$('#endEmoji').textContent=win?'🏆':'💪';$('#endTitle').textContent=title;$('#endText').textContent=`${text} +${earned} XP e +${Math.floor(earned/5)} fichas`;$('#endOverlay').style.display='grid'}

